async def _metadata(
    rt: Runtime, instruments: list[str], currencies: list[str], main_account: bool = False
) -> w.Meta:
    """Load (once, then cached) the instrument, currency and account data the message builders need.

    A cached entry is read without awaiting the cache, which keeps the common signing path short."""
    peek = rt.metadata.peek
    if main_account and peek("main_account", "") is None:
        await rt.metadata.get("main_account", "", partial(_load_main_account, rt))
    for name in instruments:
        if peek("instrument", name) is None:
            await rt.metadata.get("instrument", name, partial(_load_instrument, rt, name))
    for symbol in currencies:
        if peek("currency", symbol) is None:
            await rt.metadata.get("currency", symbol, partial(_load_currency, rt, symbol))
    return w.Meta(rt.metadata)


async def _load_instrument(rt: Runtime, name: str) -> dict[str, Any]:
    resp: m.ApiGetInstrumentResponse = await rt.call(
        specs.INSTRUMENT_GET_INSTRUMENT,
        m.ApiGetInstrumentRequest(instrument=name),
    )
    return codec.to_builtins(resp.result)


async def _load_currency(rt: Runtime, symbol: str) -> dict[str, Any]:
    resp: m.ApiGetCurrencyResponse = await rt.call(specs.INSTRUMENT_GET_CURRENCY, m.ApiGetCurrencyRequest())
    found: dict[str, Any] | None = None
    for c in resp.result or []:
        data = codec.to_builtins(c)
        rt.metadata.put("currency", str(c.symbol), data)
        if c.symbol == symbol:
            found = data
    if found is None:
        raise ValueError(f"unknown currency {symbol!r}")
    return found


async def _load_main_account(rt: Runtime) -> str:
    """The session's main account address, which some calls sign (contract signed.main_account)."""
    resp: m.ApiFundingAccountSummaryResponse = await rt.call(specs.ACCOUNT_FUNDING_ACCOUNT_SUMMARY, m.EmptyRequest())
    value = w.get(codec.to_builtins(resp), "result", "main_account_id")
    if not value:
        raise ValueError("no main account in account.funding_account_summary result.main_account_id")
    return str(value)


async def sign_edge_wallet_login(rt: Runtime, req: m.EdgeWalletLoginRequestInput) -> m.EdgeWalletLoginRequestInput:
    """Sign edge.wallet_login. always WalletLogin"""
    d = codec.to_builtins(req)
    sig = w.prepare_signature(rt, d, ("signature",), LOGIN_SIGNATURE_TTL_NS)
    meta = await _metadata(rt, [], [])
    struct, message = EIP712_WALLET_LOGIN, _message_wallet_login(d, meta)
    await w.sign_into(rt, sig, struct, message)
    return codec.convert(d, m.EdgeWalletLoginRequestInput)


