async def sign_order_bulk_orders(rt: Runtime, req: m.ApiBulkOrdersRequestInput) -> m.ApiBulkOrdersRequestInput:
    """Sign order.bulk_orders: every element of orders on its own, with its own nonce and expiration. Each order is signed on its own, like create_order: OrderWithBuilderFee when that order's builder is set to a non-zero address, otherwise Order. The cancel lists and time_to_live_ms are not signed."""
    body = codec.to_builtins(req)
    pending: list[tuple[dict[str, Any], StructType, dict[str, Any]]] = []
    for element in w.items(body, "orders"):
        d: dict[str, Any] = {"order": element}
        sig = w.prepare_signature(rt, d, ("order", "signature"), SIGNATURE_TTL_NS)
        meta = await _metadata(rt, w.present([w.get(e, "instrument") for e in w.items(d, "order", "legs")]), [])
        if rt.check_orders:
            w.check_order(ORDER_CHECKS, w.get(d, "order"), meta)
        if w.address_set(w.get(d, "order", "builder")):
            struct, message = EIP712_ORDER_WITH_BUILDER_FEE, _message_order_with_builder_fee(d, meta)
        else:
            struct, message = EIP712_ORDER, _message_order(d, meta)
        pending.append((sig, struct, message))
    for sig, struct, message in pending:
        await w.sign_into(rt, sig, struct, message)
    return codec.convert(body, m.ApiBulkOrdersRequestInput)


async def sign_order_create_order(rt: Runtime, req: m.ApiCreateOrderRequestInput) -> m.ApiCreateOrderRequestInput:
    """Sign order.create_order. Use OrderWithBuilderFee when order.builder is set to a non-zero address, otherwise Order."""
    d = codec.to_builtins(req)
