async def sign_transfer_transfer(rt: Runtime, req: m.ApiTransferRequestInput) -> m.ApiTransferRequestInput:
    """Sign transfer.transfer. If from_wallet_type and to_wallet_type are both set: TransferV2 when the currency id fits uint8 (<= 255), else TransferV3. If neither is set: Transfer (only for currency ids <= 255). Setting only one..."""
    d = codec.to_builtins(req)
    sig = w.prepare_signature(rt, d, ("signature",), SIGNATURE_TTL_NS)
    meta = await _metadata(rt, [], w.present([w.get(d, "currency")]))
    currency_id = meta.currency(w.get(d, "currency"))["id"]
    from_wallet, to_wallet = w.get(d, "from_wallet_type"), w.get(d, "to_wallet_type")
    if (from_wallet is None) != (to_wallet is None):
        raise ValueError("set both from_wallet_type and to_wallet_type, or neither")
    if from_wallet is None:
        if currency_id > 255:
            raise ValueError(f"currency id {currency_id} needs from_wallet_type and to_wallet_type")
        struct, message = EIP712_TRANSFER, _message_transfer(d, meta)
    elif currency_id <= 255:
        struct, message = EIP712_TRANSFER_V2, _message_transfer_v2(d, meta)
    else:
        struct, message = EIP712_TRANSFER_V3, _message_transfer_v3(d, meta)
    await w.sign_into(rt, sig, struct, message)
    return codec.convert(d, m.ApiTransferRequestInput)


async def sign_transfer_withdrawal(rt: Runtime, req: m.ApiWithdrawalRequestInput) -> m.ApiWithdrawalRequestInput:
    """Sign transfer.withdrawal. Withdrawal when the currency id fits uint8 (<= 255), else WithdrawalV2."""
    d = codec.to_builtins(req)
    sig = w.prepare_signature(rt, d, ("signature",), SIGNATURE_TTL_NS)
    meta = await _metadata(rt, [], w.present([w.get(d, "currency")]))
    if meta.currency(w.get(d, "currency"))["id"] <= 255:
        struct, message = EIP712_WITHDRAWAL, _message_withdrawal(d, meta)
    else:
        struct, message = EIP712_WITHDRAWAL_V2, _message_withdrawal_v2(d, meta)
    await w.sign_into(rt, sig, struct, message)
    return codec.convert(d, m.ApiWithdrawalRequestInput)


